 it('持续秒数在REPORT/ALL谓词往返，PUSH/CLOUD保持即时',()=>{
  const conditions=[{propertyKey:'temperature',operator:'GT' as const,value:new ExactDecimal('40')}]
  const report=automationTriggerConfig(source,'ALL',conditions,30)
  expect((report as any).propertyPredicate.durationSeconds).toBe(30)
  expect(automationPropertyTrigger(report)?.durationSeconds).toBe(30)
  const changed=automationChangedTriggerValue(source,'REPORT','ALL',conditions,30)
  expect((changed as any).propertyPredicate.durationSeconds).toBe(30)
  expect(automationPropertyTrigger(changed)?.durationSeconds).toBe(30)
  expect(()=>automationChangedTriggerValue(source,'PUSH','ALL',conditions,30)).toThrow()
  expect(()=>automationChangedTriggerValue(source,'REPORT','ALL',conditions,86401)).toThrow()
  expect(automationDurationLabel(0)).toBe('即时')
  expect(automationDurationLabel(30)).toBe('30秒')
  expect(automationDurationLabel(60)).toBe('1分钟')
  expect(automationDurationLabel(90)).toBe('90秒')
  expect(automationDurationLabel(3600)).toBe('1小时')
  expect(automationDurationLabel(86400)).toBe('1天')
 })
it('MIXED不承载持续窗口，转换归零且直接配置30秒被拒',()=>{
 const conditions=[{propertyKey:'temperature',operator:'GT' as const,value:new ExactDecimal('40')}]
 const mixedRows=automationReportAsMixed('PROPERTY_REPORTED',automationTriggerConfig(source,'ALL',conditions,30))!
 expect((mixedRows[0]!.options as any).propertyPredicate.durationSeconds).toBe(0)
 const mixed=(options:unknown)=>({schemaVersion:3,relation:'ANY',timezoneMode:'FOLLOW_PROJECT',triggers:[{kind:'PROPERTY_REPORTED',enabled:true,options}]})
 expect(automationMixedConfig('MIXED',mixed(automationTriggerConfig(source,'ALL',conditions,30)))).toBeUndefined()
 expect(automationMixedConfig('MIXED',mixed(automationTriggerConfig(source,'ALL',conditions,0)))).toBeTruthy()
})
